styl:
.brad-full { border-radius: 32px !important; }
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb16 { padding-bottom: 16px; }
.pb24 { padding-bottom: 24px; }
.pb44 { padding-bottom: 44px; }
.pt44 { padding-top: 44px; }
.h-12 { font-size: 8px;
  line-height: 12px;
  height: 12px; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
.w100 { width: 100%; }
.block-220 { max-width: 220px;
  display: block;
  display: inline-block;
  padding: 24px 10px 24px 32px;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .block-220 { max-width: 100% !important;
    display: block !important;
    margin: 0 auto !important;
    text-align: center !important;
    padding: 0px 24px 0 24px !important;
    width: auto !important; }
}
@media screen and (max-width: 600px) {
  .ta-mob { text-align: center !important; }
}
.right-img { float: none;
  display: inline-block;
  width: 180px;
  vertical-align: middle;
  float: none; }
@media screen and (max-width: 600px) {
  .right-img { float: none !important;
    display: block !important;
    margin: 0 auto !important;
    padding-right: 0 !important;
    padding-bottom: 24px !important;
    width: 1px !important;
    max-width: 0.1px !important; }
}
.right-top { float: none;
  display: inline-block;
  width: 1px;
  max-width: 0.1px;
  vertical-align: middle;
  float: none; }
@media screen and (max-width: 600px) {
  .right-top { float: none !important;
    display: block !important;
    margin: 0 auto !important;
    padding-right: 0 !important;
    padding-bottom: 24px !important;
    padding-top: 20px !important;
    width: 180px !important;
    max-width: 180px !important; }
}
.first-block { background: url("https://fsms.quadcode.com/storage/public/d6/pa/f43ursrq72d918j0/bg-1.png") center no-repeat;
  background-color: #f5fdfb;
  background-size: cover !important;
  border-radius: 24px; }
.second-block { background: url("https://fsms.quadcode.com/storage/public/d6/pa/f43s2mcraq8anaag/bg-2.png") center no-repeat;
  background-color: #fff8f0;
  background-size: cover !important;
  border-radius: 24px; }
.third-block { background: url("https://fsms.quadcode.com/storage/public/d6/pa/f43s2mcraq8anab0/bg-3.png") center no-repeat;
  background-color: #fff5f8;
  background-size: cover !important;
  border-radius: 24px; }
